  1→/**
  2→ * MessageQueue - Batches messages with debounce for idle-time optimization.
  3→ *
  4→ * Buffers incoming messages and auto-flushes after a configurable debounce window.
  5→ * Manual flush is available for immediate batch retrieval.
  6→ */
  7→
  8→export type Message = string;
  9→export type BatchPayload = Message[];
 10→
 11→export interface MessageQueueOptions {
 12→  /** Debounce window in milliseconds (default: 300, must be non-negative) */
 13→  debounceMs?: number;
 14→  /** Callback invoked on auto-flush (debounce expiry) */
 15→  onFlush?: (batch: BatchPayload) => void | Promise<void>;
 16→  /** Error handler for failures in onFlush callback */
 17→  onError?: (error: Error, batch: BatchPayload) => void;
 18→}
 19→
 20→export class MessageQueue {
 21→  private buffer: Message[] = [];
 22→  private timer: ReturnType<typeof setTimeout> | null = null;
 23→  private readonly debounceMs: number;
 24→  private readonly options: MessageQueueOptions;
 25→  private destroyed = false;
 26→
 27→  constructor(options: MessageQueueOptions = {}) {
 28→    const debounce = options.debounceMs ?? 300;
 29→    if (debounce < 0) {
 30→      throw new Error("debounceMs must be non-negative");
 31→    }
 32→    this.debounceMs = debounce;
 33→    this.options = options;
 34→  }
 35→
 36→  /**
 37→   * Add message to buffer and reset debounce timer.
 38→   * @throws Error if queue has been destroyed
 39→   */
 40→  enqueue(message: Message): void {
 41→    if (this.destroyed) {
 42→      throw new Error("MessageQueue has been destroyed");
 43→    }
 44→
 45→    this.buffer.push(message);
 46→    this.resetTimer();
 47→  }
 48→
 49→  /**
 50→   * Manually flush buffer, canceling pending timer.
 51→   * @returns Current batch (may be empty array)
 52→   */
 53→  flush(): BatchPayload {
 54→    this.cancelTimer();
 55→    const batch = [...this.buffer];
 56→    this.buffer = [];
 57→    return batch;
 58→  }
 59→
 60→  /**
 61→   * Current buffer size.
 62→   */
 63→  get pending(): number {
 64→    return this.buffer.length;
 65→  }
 66→
 67→  /**
 68→   * Cleanup timer and prevent further enqueues.
 69→   */
 70→  destroy(): void {
 71→    this.cancelTimer();
 72→    this.destroyed = true;
 73→    this.buffer = [];
 74→  }
 75→
 76→  private resetTimer(): void {
 77→    this.cancelTimer();
 78→    this.timer = setTimeout(() => {
 79→      this.autoFlush().catch((err) => {
 80→        if (this.options.onError) {
 81→          this.options.onError(err, this.buffer);
 82→        } else {
 83→          console.error("MessageQueue autoFlush error:", err);
 84→        }
 85→      });
 86→    }, this.debounceMs);
 87→  }
 88→
 89→  private cancelTimer(): void {
 90→    if (this.timer) {
 91→      clearTimeout(this.timer);
 92→      this.timer = null;
 93→    }
 94→  }
 95→
 96→  private async autoFlush(): Promise<void> {
 97→    const batch = this.flush(); // Sync grab + reset
 98→    if (batch.length > 0) {
 99→      await this.options.onFlush?.(batch);
100→    }
101→  }
102→}
