  1→import {
  2→  createSteeringMessage,
  3→  type PendingRecovery,
  4→  type SteeringMessage,
  5→} from "../../types/session";
  6→import { formatSteeringMessages } from "./session-helpers";
  7→
  8→export interface SteeringAddResult {
  9→  evicted: boolean;
 10→  evictedMessage: SteeringMessage | null;
 11→}
 12→
 13→export class SteeringManager {
 14→  private steeringBuffer: SteeringMessage[] = [];
 15→  private injectedSteeringDuringQuery: SteeringMessage[] = [];
 16→  private pendingRecovery: PendingRecovery | null = null;
 17→  private _evictionCount = 0;
 18→
 19→  constructor(
 20→    private readonly maxSteeringMessages: number,
 21→    private readonly pendingRecoveryTimeoutMs: number
 22→  ) {}
 23→
 24→  getSteeringCount(): number {
 25→    return this.steeringBuffer.length;
 26→  }
 27→
 28→  hasSteeringMessages(): boolean {
 29→    return this.steeringBuffer.length > 0;
 30→  }
 31→
 32→  /** Total messages evicted since last reset. */
 33→  get evictionCount(): number {
 34→    return this._evictionCount;
 35→  }
 36→
 37→  addSteering(
 38→    message: string,
 39→    messageId: number,
 40→    receivedDuringTool?: string
 41→  ): SteeringAddResult {
 42→    let evictedMessage: SteeringMessage | null = null;
 43→    if (this.steeringBuffer.length >= this.maxSteeringMessages) {
 44→      evictedMessage = this.steeringBuffer.shift() ?? null;
 45→      this._evictionCount++;
 46→    }
 47→
 48→    const steeringMessage = createSteeringMessage(
 49→      message,
 50→      messageId,
 51→      receivedDuringTool
 52→    );
 53→    this.steeringBuffer.push(steeringMessage);
 54→    return { evicted: evictedMessage !== null, evictedMessage };
 55→  }
 56→
 57→  consumeSteering(): string | null {
 58→    if (!this.steeringBuffer.length) {
 59→      return null;
 60→    }
 61→    const formatted = formatSteeringMessages(this.steeringBuffer);
 62→    this.steeringBuffer = [];
 63→    return formatted;
 64→  }
 65→
 66→  peekSteering(): string | null {
 67→    if (!this.steeringBuffer.length) return null;
 68→    return formatSteeringMessages(this.steeringBuffer);
 69→  }
 70→
 71→  extractSteeringMessages(): SteeringMessage[] {
 72→    if (!this.steeringBuffer.length) return [];
 73→    const messages = [...this.steeringBuffer];
 74→    this.steeringBuffer = [];
 75→    return messages;
 76→  }
 77→
 78→  trackBufferedMessagesForInjection(): number {
 79→    if (!this.steeringBuffer.length) {
 80→      return 0;
 81→    }
 82→    this.injectedSteeringDuringQuery.push(...this.steeringBuffer);
 83→    return this.steeringBuffer.length;
 84→  }
 85→
 86→  getInjectedCount(): number {
 87→    return this.injectedSteeringDuringQuery.length;
 88→  }
 89→
 90→  restoreInjectedSteering(): number {
 91→    const injectedCount = this.injectedSteeringDuringQuery.length;
 92→    if (!injectedCount) {
 93→      return 0;
 94→    }
 95→
 96→    this.steeringBuffer = [...this.injectedSteeringDuringQuery, ...this.steeringBuffer];
 97→    this.injectedSteeringDuringQuery = [];
 98→    return injectedCount;
 99→  }
100→
101→  clearInjectedSteeringTracking(): void {
102→    this.injectedSteeringDuringQuery = [];
103→  }
104→
105→  setPendingRecovery(
106→    messages: SteeringMessage[],
107→    chatId: number,
108→    messageId?: number
109→  ): void {
110→    this.pendingRecovery = {
111→      messages,
112→      promptedAt: Date.now(),
113→      state: "awaiting",
114→      chatId,
115→      messageId,
116→    };
117→  }
118→
119→  getPendingRecovery(): PendingRecovery | null {
120→    if (!this.pendingRecovery) return null;
121→
122→    const elapsed = Date.now() - this.pendingRecovery.promptedAt;
123→    if (elapsed > this.pendingRecoveryTimeoutMs) {
124→      this.pendingRecovery = null;
125→      return null;
126→    }
127→
128→    return this.pendingRecovery;
129→  }
130→
131→  resolvePendingRecovery(): SteeringMessage[] | null {
132→    const recovery = this.getPendingRecovery();
133→    if (!recovery || recovery.state === "resolved") return null;
134→
135→    recovery.state = "resolved";
136→    const messages = recovery.messages;
137→    this.pendingRecovery = null;
138→    return messages;
139→  }
140→
141→  clearPendingRecovery(): number {
142→    const discarded = this.pendingRecovery?.messages.length ?? 0;
143→    this.pendingRecovery = null;
144→    return discarded;
145→  }
146→
147→  hasPendingRecovery(): boolean {
148→    return this.getPendingRecovery() !== null;
149→  }
150→
151→  reset(): void {
152→    this.steeringBuffer = [];
153→    this.injectedSteeringDuringQuery = [];
154→    this.pendingRecovery = null;
155→    this._evictionCount = 0;
156→  }
157→}
