  1→export type ActivityState = "idle" | "working" | "waiting";
  2→export type QueryState = "idle" | "preparing" | "running" | "aborting" | "completing";
  3→
  4→export interface SessionRuntimeState {
  5→  activityState: ActivityState;
  6→  queryState: QueryState;
  7→  stopRequested: boolean;
  8→  wasInterruptedByNewMessage: boolean;
  9→  isInterrupting: boolean;
 10→  generation: number;
 11→}
 12→
 13→export interface InterruptConsumptionResult {
 14→  wasInterrupted: boolean;
 15→  nextState: SessionRuntimeState;
 16→}
 17→
 18→export interface BeginInterruptResult {
 19→  started: boolean;
 20→  nextState: SessionRuntimeState;
 21→}
 22→
 23→export function createInitialSessionRuntimeState(): SessionRuntimeState {
 24→  return {
 25→    activityState: "idle",
 26→    queryState: "idle",
 27→    stopRequested: false,
 28→    wasInterruptedByNewMessage: false,
 29→    isInterrupting: false,
 30→    generation: 0,
 31→  };
 32→}
 33→
 34→export function transitionActivityState(
 35→  state: SessionRuntimeState,
 36→  nextActivityState: ActivityState
 37→): SessionRuntimeState {
 38→  return { ...state, activityState: nextActivityState };
 39→}
 40→
 41→export function transitionQueryState(
 42→  state: SessionRuntimeState,
 43→  nextQueryState: QueryState
 44→): SessionRuntimeState {
 45→  return { ...state, queryState: nextQueryState };
 46→}
 47→
 48→export function startProcessingTransition(
 49→  state: SessionRuntimeState
 50→): SessionRuntimeState {
 51→  return transitionQueryState(state, "preparing");
 52→}
 53→
 54→export function stopProcessingTransition(
 55→  state: SessionRuntimeState
 56→): SessionRuntimeState {
 57→  return transitionQueryState(state, "idle");
 58→}
 59→
 60→export function startQueryTransition(state: SessionRuntimeState): SessionRuntimeState {
 61→  return {
 62→    ...state,
 63→    queryState: "running",
 64→    stopRequested: false,
 65→  };
 66→}
 67→
 68→export function completeQueryTransition(
 69→  state: SessionRuntimeState
 70→): SessionRuntimeState {
 71→  return transitionQueryState(state, "completing");
 72→}
 73→
 74→export function finalizeQueryTransition(
 75→  state: SessionRuntimeState
 76→): SessionRuntimeState {
 77→  return transitionQueryState(state, "idle");
 78→}
 79→
 80→export function requestStopDuringRunningTransition(
 81→  state: SessionRuntimeState
 82→): SessionRuntimeState {
 83→  return {
 84→    ...state,
 85→    stopRequested: true,
 86→    queryState: "aborting",
 87→  };
 88→}
 89→
 90→export function requestStopDuringPreparingTransition(
 91→  state: SessionRuntimeState
 92→): SessionRuntimeState {
 93→  return {
 94→    ...state,
 95→    stopRequested: true,
 96→  };
 97→}
 98→
 99→export function clearStopRequestedTransition(
100→  state: SessionRuntimeState
101→): SessionRuntimeState {
102→  return {
103→    ...state,
104→    stopRequested: false,
105→  };
106→}
107→
108→export function markInterruptFlag(state: SessionRuntimeState): SessionRuntimeState {
109→  return {
110→    ...state,
111→    wasInterruptedByNewMessage: true,
112→  };
113→}
114→
115→export function consumeInterruptFlagTransition(
116→  state: SessionRuntimeState
117→): InterruptConsumptionResult {
118→  if (!state.wasInterruptedByNewMessage) {
119→    return {
120→      wasInterrupted: false,
121→      nextState: { ...state, wasInterruptedByNewMessage: false },
122→    };
123→  }
124→
125→  return {
126→    wasInterrupted: true,
127→    nextState: {
128→      ...state,
129→      wasInterruptedByNewMessage: false,
130→      stopRequested: false,
131→    },
132→  };
133→}
134→
135→export function beginInterruptTransition(
136→  state: SessionRuntimeState
137→): BeginInterruptResult {
138→  if (state.isInterrupting) {
139→    return { started: false, nextState: state };
140→  }
141→  return {
142→    started: true,
143→    nextState: { ...state, isInterrupting: true },
144→  };
145→}
146→
147→export function endInterruptTransition(
148→  state: SessionRuntimeState
149→): SessionRuntimeState {
150→  return {
151→    ...state,
152→    isInterrupting: false,
153→  };
154→}
155→
156→export function incrementGenerationTransition(
157→  state: SessionRuntimeState
158→): SessionRuntimeState {
159→  return {
160→    ...state,
161→    generation: state.generation + 1,
162→  };
163→}
164→
165→export function isQueryRunning(state: SessionRuntimeState): boolean {
166→  return (
167→    state.queryState === "running" ||
168→    state.queryState === "aborting" ||
169→    state.queryState === "completing"
170→  );
171→}
172→
173→export function isQueryProcessing(state: SessionRuntimeState): boolean {
174→  return (
175→    state.queryState === "preparing" ||
176→    state.queryState === "running" ||
177→    state.queryState === "completing"
178→  );
179→}
