  73→export type { ActivityState, QueryState } from "./state-machine";
  74→
  75→const initialRuntimeState = createInitialSessionRuntimeState();
  76→const SESSIONS_DIR = "/tmp/soma-sessions";
  77→
  78→export class ClaudeSession {
  79→  readonly sessionKey: string;
  80→  readonly workingDir: string;
  81→  readonly chatCaptureService: ChatCaptureService | null = null;
  82→
  83→  sessionId: string | null = null;
  84→  lastActivity: Date | null = null;
  85→  queryStarted: Date | null = null;
  86→  currentTool: string | null = null;
  87→  lastTool: string | null = null;
  88→  lastError: string | null = null;
  89→  lastErrorTime: Date | null = null;
  90→  lastUsage: TokenUsage | null = null;
  91→  lastMessage: string | null = null;
  92→
  93→  // Context window from Claude Code (claude-dashboard style)
  94→  contextWindowUsage: {
  95→    input_tokens: number;
  96→    cache_creation_input_tokens: number;
  97→    cache_read_input_tokens: number;
  98→  } | null = null;
  99→  contextWindowSize = 200_000;
 100→
 101→  // Cumulative token tracking
 102→  sessionStartTime: Date | null = null;
 103→  totalInputTokens = 0;
 104→  totalOutputTokens = 0;
 105→  totalCacheReadTokens = 0;
 106→  totalCacheCreateTokens = 0;
 107→  totalQueries = 0;
 108→
 109→  // Cumulative tool usage (session-wide)
 110→  cumulativeToolDurations: Record<string, { count: number; totalMs: number }> = {};
 111→
 112→  constructor(
 113→    sessionKey = "default",
 114→    chatCaptureService: ChatCaptureService | null = null,
 115→    options?: {
 116→      workingDir?: string;
 117→      providerOrchestrator?: ProviderOrchestrator | null;
 118→    }
 119→  ) {
 120→    this.sessionKey = sessionKey;
 121→    this.workingDir = options?.workingDir || WORKING_DIR;
 122→    this.chatCaptureService = chatCaptureService;
 123→    this.providerOrchestrator = options?.providerOrchestrator ?? null;
 124→  }
 125→
 126→  contextLimitWarned = false;
 127→  warned70 = false;
 128→  warned85 = false;
 129→  warned95 = false;
 130→  recentlyRestored = false;
 131→  messagesSinceRestore = 0;
 132→
 133→  private abortController: AbortController | null = null;
 134→  private _queryState: QueryState = initialRuntimeState.queryState;
 135→  private stopRequested = initialRuntimeState.stopRequested;
 136→  private _generation = initialRuntimeState.generation;
 137→  private _wasInterruptedByNewMessage = initialRuntimeState.wasInterruptedByNewMessage;
 138→  private _isInterrupting = initialRuntimeState.isInterrupting;
 139→  private steering = new SteeringManager(100, PENDING_RECOVERY_TIMEOUT_MS);
 140→
 141→  choiceState: ChoiceState | null = null;
 142→  pendingDirectInput: DirectInputState | null = null;
 143→  parseTextChoiceState: ParseTextChoiceState | null = null;
 144→  nextQueryContext: string | null = null; // Context to prepend to next query
 145→  private _activityState: ActivityState = initialRuntimeState.activityState;
 146→
 147→  // Rate limit fallback state
 148→  temporaryModelOverride: ModelId | null = null;
 149→  rateLimitState = {
 150→    consecutiveFailures: 0,
 151→    cooldownUntil: null as number | null,
 152→    opusResetsAt: null as string | null,
 153→  };
 154→
 155→  private readonly queryRuntimeHooks = createQueryRuntimeHooks({
 156→    getStopRequested: () => this.stopRequested,
 157→    getSteeringCount: () => this.steering.getSteeringCount(),
 158→    trackBufferedMessagesForInjection: () =>
 159→      this.steering.trackBufferedMessagesForInjection(),
 160→    consumeSteering: () => this.consumeSteering(),
 161→    getInjectedCount: () => this.steering.getInjectedCount(),
 162→  });
 163→  // Legacy aliases kept for existing regression tests and compatibility.
 164→  private readonly preToolUseHook = this.queryRuntimeHooks.preToolUseHook;
 165→  private readonly postToolUseHook = this.queryRuntimeHooks.postToolUseHook;
 166→  private providerOrchestrator: ProviderOrchestrator | null;
 167→
 168→  private getRuntimeState(): SessionRuntimeState {
 169→    return {
 170→      activityState: this._activityState,
 171→      queryState: this._queryState,
 172→      stopRequested: this.stopRequested,
 173→      wasInterruptedByNewMessage: this._wasInterruptedByNewMessage,
 174→      isInterrupting: this._isInterrupting,
 175→      generation: this._generation,
 176→    };
 177→  }
 178→
 179→  private applyRuntimeState(nextState: SessionRuntimeState): void {
 180→    this._activityState = nextState.activityState;
 181→    this._queryState = nextState.queryState;
 182→    this.stopRequested = nextState.stopRequested;
 183→    this._wasInterruptedByNewMessage = nextState.wasInterruptedByNewMessage;
 184→    this._isInterrupting = nextState.isInterrupting;
 185→    this._generation = nextState.generation;
 186→  }
 187→
 188→  get activityState(): ActivityState {
 189→    return this._activityState;
 190→  }
 191→
 192→  setActivityState(state: ActivityState): void {
 193→    console.log(`[ACTIVITY] ${this._activityState} → ${state}`);
 194→    this.applyRuntimeState(transitionActivityState(this.getRuntimeState(), state));
 195→  }
 196→
 197→  setProviderOrchestrator(orchestrator: ProviderOrchestrator | null): void {
 198→    this.providerOrchestrator = orchestrator;
 199→  }
 200→
 201→  private resolveProviderIdentity(): SessionIdentity {
 202→    try {
 203→      return parseSessionKey(this.sessionKey);
 204→    } catch {
 205→      const threadId = this.sessionKey.replace(/[:/]/g, "-").trim() || "main";
 206→      return createSessionIdentity({
 207→        tenantId: "default",
 208→        channelId: "legacy",
 209→        threadId,
 210→      });
 211→    }
 212→  }
 213→
 214→  private async refreshContextWindowUsageFromTranscript(
 215→    minTimestampMs: number
 216→  ): Promise<boolean> {
 217→    if (!this.sessionId) return false;
 218→
 219→    for (let attempt = 0; attempt < 3; attempt++) {
 220→      const usage = findLatestMainAssistantContextUsageFromTranscript(
 221→        this.sessionId,
 222→        this.workingDir,
 223→        minTimestampMs
 224→      );
 225→      if (usage) {
 226→        this.contextWindowUsage = usage;
 227→        return true;
 228→      }
 229→      if (attempt < 2) await Bun.sleep(50);
 230→    }
 231→    return false;
 232→  }
 233→
 234→  get isActive(): boolean {
 235→    return this.sessionId !== null;
 236→  }
 237→
 238→  get isRunning(): boolean {
 239→    return isQueryRunning(this.getRuntimeState());
 240→  }
 241→
 242→  get queryState(): QueryState {
 243→    return this._queryState;
 244→  }
 245→
 246→  get currentContextTokens(): number {
 247→    return (
 248→      this.getContextTokensFromSnapshot() ?? this.getContextTokensFromCumulatives()
 249→    );
 250→  }
 251→
 252→  private getContextTokensFromSnapshot(): number | null {
 253→    if (!this.contextWindowUsage) return null;
 254→    const {
 255→      input_tokens = 0,
 256→      cache_creation_input_tokens = 0,
 257→      cache_read_input_tokens = 0,
 258→    } = this.contextWindowUsage;
 259→    // Per Anthropic API docs: these 3 fields are mutually exclusive (no overlap).
 260→    // total = all tokens that occupy the context window.
 261→    const total = input_tokens + cache_creation_input_tokens + cache_read_input_tokens;
 262→    return total > 0 ? total : null;
 263→  }
 264→
 265→  private getContextTokensFromCumulatives(): number {
 266→    return this.totalInputTokens + this.totalCacheCreateTokens;
 267→  }
 268→
 269→  /**
 270→   * Format cumulative tool stats for display.
 271→   * Returns string like: "Bash×12: 134.8s | Grep×5: 84.6s"
 272→   */
 273→  formatToolStats(): string {
 274→    const tools = Object.entries(this.cumulativeToolDurations);
 275→    if (tools.length === 0) return "";
 276→
 277→    return tools
 278→      .sort((a, b) => b[1].totalMs - a[1].totalMs) // Sort by total time desc
 279→      .slice(0, 5) // Top 5 tools
 280→      .map(([name, { count, totalMs }]) => {
 281→        const secs = (totalMs / 1000).toFixed(1);
 282→        return `${name}×${count}: ${secs}s`;
 283→      })
 284→      .join(" | ");
 285→  }
 286→
 287→  get needsSave(): boolean {
 288→    // DISABLED: auto-save causing issues with context overflow loops
 289→    return false;
 290→    // return this.contextLimitWarned && !this.recentlyRestored;
 291→  }
 292→
 293→  get needsWarning70(): boolean {
 294→    return this.warned70 && !this.recentlyRestored;
 295→  }
