 490→  startProcessing(): () => void {
 491→    this.applyRuntimeState(startProcessingTransition(this.getRuntimeState()));
 492→    const PROCESSING_TIMEOUT_MS = 60_000;
 493→    let released = false;
 494→    const timer = setTimeout(() => {
 495→      if (!released && this.isProcessing) {
 496→        console.error(
 497→          `[STUCK] isProcessing stuck for ${PROCESSING_TIMEOUT_MS / 1000}s, auto-releasing`
 498→        );
 499→        this.applyRuntimeState(stopProcessingTransition(this.getRuntimeState()));
 500→      }
 501→    }, PROCESSING_TIMEOUT_MS);
 502→    return () => {
 503→      released = true;
 504→      clearTimeout(timer);
 505→      const prevState = this._queryState;
 506→      this.applyRuntimeState(stopProcessingTransition(this.getRuntimeState()));
 507→      console.log(
 508→        `[PROCESSING] stopProcessing() called: ${prevState} → idle, steering=${this.steering.getSteeringCount()}`
 509→      );
 510→      if (this.steering.hasSteeringMessages()) {
 511→        console.log(
 512→          `[STEERING] Keeping ${this.steering.getSteeringCount()} unconsumed messages for next query`
 513→        );
 514→      }
 515→    };
 516→  }
