 526→  async stop(): Promise<"stopped" | "pending" | false> {
 527→    if (this._queryState === "running" && this.abortController) {
 528→      this.applyRuntimeState(
 529→        requestStopDuringRunningTransition(this.getRuntimeState())
 530→      );
 531→      this.abortController.abort();
 532→      console.log("Stop requested - aborting current query");
 533→
 534→      // Wait for query to actually stop (max 5s)
 535→      const start = Date.now();
 536→      while (this.queryState !== "idle" && Date.now() - start < 5000) {
 537→        await Bun.sleep(50);
 538→      }
 539→
 540→      if (this.queryState === "idle") {
 541→        console.log("Stop completed - query stopped");
 542→      } else {
 543→        console.warn("Stop timeout - query still running after 5s");
 544→      }
 545→
 546→      return "stopped";
 547→    }
 548→
 549→    if (this._queryState === "preparing") {
 550→      this.applyRuntimeState(
 551→        requestStopDuringPreparingTransition(this.getRuntimeState())
 552→      );
 553→      console.log("Stop requested - will cancel before query starts");
 554→      return "pending";
 555→    }
 556→
 557→    return false;
 558→  }
