 560→  async sendMessageStreaming(
 561→    message: string,
 562→    statusCallback: StatusCallback,
 563→    chatId?: number,
 564→    modelContext: ConfigContext = "general"
 565→  ): Promise<string> {
 566→    // Re-entrancy guard: prevent concurrent calls from corrupting session state
 567→    if (this.isRunning) {
 568→      console.warn(
 569→        `[QUERY] Re-entrant sendMessageStreaming blocked (queryState=${this.queryState}, sessionId=${this.sessionId?.slice(0, 8) || "null"})`
 570→      );
 571→      throw new Error("sendMessageStreaming is already running. Concurrent calls are not supported.");
 572→    }
 573→
 574→    if (chatId) process.env.TELEGRAM_CHAT_ID = String(chatId);
 575→
 576→    const prevInjectedCount = this.steering.restoreInjectedSteering();
 577→    if (prevInjectedCount > 0) {
 578→      console.log(
 579→        `[QUERY START] Restored ${prevInjectedCount} injected message(s) to buffer before new query. Buffer now: ${this.steering.getSteeringCount()}`
 580→      );
 581→    }
 582→    this.steering.clearInjectedSteeringTracking();
 583→    console.log(
 584→      `[QUERY START DEBUG] Cleared injected tracking (was: ${prevInjectedCount}), buffer: ${this.steering.getSteeringCount()}`
 585→    );
 586→
 587→    const queryGeneration = this._generation;
 588→    const isNewSession = !this.isActive;
 589→    console.log(
 590→      `[QUERY] Starting: sessionId=${this.sessionId?.slice(0, 8) || "null"}, isNewSession=${isNewSession}, isActive=${this.isActive}`
 591→    );
 592→
 593→    const thinkingTokens = getThinkingLevel(message);
 594→    const thinkingLabel =
 595→      { 0: "off", 10000: "normal", 50000: "deep" }[thinkingTokens] ??
 596→      String(thinkingTokens);
 597→
 598→    let messageToSend = message;
 599→    const pendingSteering = this.getPendingSteering();
 600→    if (pendingSteering) {
 601→      console.log(
 602→        `[STEERING] Prepending ${pendingSteering.split("\n---\n").length} pending messages to query`
 603→      );
 604→      messageToSend = `[MESSAGES SENT DURING PREVIOUS EXECUTION - user sent these while you were working]\n${pendingSteering}\n[END PREVIOUS MESSAGES]\n\n[NEW MESSAGE]\n${messageToSend}`;
 605→    }
 606→
 607→    if (this.nextQueryContext) {
 608→      console.log("[CONTEXT] Prepending recovered context from previous session");
 609→      messageToSend = `${this.nextQueryContext}\n\n${messageToSend}`;
 610→      this.nextQueryContext = null;
 611→    }
 612→
 613→    if (isNewSession) {
 614→      const now = new Date();
 615→      const datePrefix = `[Current date/time: ${now.toLocaleDateString("en-US", {
 616→        weekday: "long",
 617→        year: "numeric",
 618→        month: "long",
 619→        day: "numeric",
 620→        hour: "2-digit",
 621→        minute: "2-digit",
 622→        timeZoneName: "short",
 623→      })}]\n\n`;
 624→      messageToSend = datePrefix + messageToSend;
 625→    }
 626→
 627→    if (this.temporaryModelOverride && this.rateLimitState.opusResetsAt) {
 628→      const resetTime = new Date(this.rateLimitState.opusResetsAt).getTime();
 629→      if (Date.now() >= resetTime) {
 630→        console.log("[RATE-LIMIT] Opus reset time passed, clearing override");
 631→        this.temporaryModelOverride = null;
 632→        this.rateLimitState.opusResetsAt = null;
 633→        this.rateLimitState.consecutiveFailures = 0;
 634→      }
 635→    }
 636→
 637→    const effectiveModel =
 638→      this.temporaryModelOverride ?? getModelForContext(modelContext);
 639→    if (this.temporaryModelOverride) {
 640→      console.log(
 641→        `[RATE-LIMIT] Using fallback model: ${MODEL_DISPLAY_NAMES[this.temporaryModelOverride] || this.temporaryModelOverride}`
 642→      );
 643→    }
 644→
 645→    if (this.sessionId && !isNewSession) {
 646→      console.log(
 647→        `RESUMING session ${this.sessionId.slice(0, 8)}... (thinking=${thinkingLabel})`
 648→      );
 649→    } else {
 650→      console.log(`STARTING new Claude session (thinking=${thinkingLabel})`);
 651→      this.sessionId = null;
 652→    }
 653→
 654→    if (this.stopRequested) {
 655→      console.log("Query cancelled before starting");
 656→      this.applyRuntimeState(clearStopRequestedTransition(this.getRuntimeState()));
 657→      throw new Error("Query cancelled");
 658→    }
 659→
 660→    this.abortController = new AbortController();
 661→
 662→    // Explicitly load CLAUDE.md from working directory (resolving symlinks)
 663→    let claudeMdContent = "";
 664→    try {
 665→      const { realpathSync } = require("fs");
 666→      const resolvedCwd = realpathSync(this.workingDir);
 667→      const claudeMdPath = `${resolvedCwd}/CLAUDE.md`;
 668→      if (existsSync(claudeMdPath)) {
 669→        claudeMdContent = readFileSync(claudeMdPath, "utf-8");
 670→        console.log(`[SESSION] Loaded CLAUDE.md from ${claudeMdPath} (${claudeMdContent.length} chars)`);
 671→      } else {
 672→        console.warn(`[SESSION] No CLAUDE.md found at ${claudeMdPath}`);
 673→      }
 674→    } catch (err) {
 675→      console.error(`[SESSION] Failed to load CLAUDE.md:`, err);
 676→    }
 677→    const claudeMdSection = claudeMdContent
 678→      ? `\n\n# Project Instructions (CLAUDE.md)\n${claudeMdContent}\n`
 679→      : "";
 680→
 681→    const runtimeOptions = buildQueryRuntimeOptions({
 682→      model: effectiveModel,
 683→      cwd: this.workingDir,
 684→      systemPrompt: `${SAFETY_PROMPT}\n\n${UI_ASKUSER_INSTRUCTIONS}\n\n${CHAT_HISTORY_ACCESS_INFO}${claudeMdSection}`,
 685→      mcpServers: MCP_SERVERS,
 686→      maxThinkingTokens: thinkingTokens,
 687→      additionalDirectories: ALLOWED_PATHS,
 688→      resumeSessionId: this.sessionId,
 689→      pathToClaudeCodeExecutable: process.env.CLAUDE_CODE_PATH,
 690→      abortController: this.abortController,
 691→      hooks: this.queryRuntimeHooks,
 692→    });
 693→
 694→    this.applyRuntimeState(startQueryTransition(this.getRuntimeState()));
 695→    this.setActivityState("working");
 696→    this.queryStarted = new Date();
 697→    const queryStartedMs = this.queryStarted.getTime();
 698→    this.currentTool = null;
 699→
 700→    let queryCompleted = false;
 701→    let runtimeResult: Awaited<ReturnType<typeof executeQueryRuntime>> | null = null;
 702→
 703→    const contextUsagePercentBefore = this.contextWindowUsage
 704→      ? (this.currentContextTokens / this.contextWindowSize) * 100
 705→      : undefined;
 706→    let usageBefore: UsageSnapshot | null = null;
 707→    let usageAfter: UsageSnapshot | null = null;
 708→
 709→    try {
 710→      captureUsageSnapshot()
 711→        .then((u) => {
 712→          usageBefore = u;
 713→        })
 714→        .catch(() => {});
 715→
 716→      if (this.chatCaptureService && this.sessionId) {
 717→        this.chatCaptureService
 718→          .captureUserMessage(
 719→            this.sessionKey,
 720→            this.sessionId,
 721→            getModelForContext(modelContext),
 722→            message
 723→          )
 724→          .catch((err) =>
 725→            console.error("[ChatCapture] Failed to capture user message:", err)
 726→          );
 727→      }
 728→
 729→      runtimeResult = await executeQueryRuntime({
 730→        prompt: messageToSend,
 731→        options: runtimeOptions,
 732→        statusCallback,
 733→        queryGeneration,
 734→        getCurrentGeneration: () => this._generation,
 735→        shouldStop: () => this.stopRequested,
 736→        onSessionId: (sessionId: string) => {
 737→          if (this.sessionId) {
 738→            return;
 739→          }
 740→          this.sessionId = sessionId;
 741→          console.log(`GOT session_id: ${this.sessionId.slice(0, 8)}...`);
 742→          this.saveSession();
 743→        },
 744→        onToolDisplay: (toolDisplay: string) => {
 745→          this.currentTool = toolDisplay;
 746→          this.lastTool = toolDisplay;
 747→        },
 748→        onRefreshContextWindowUsageFromTranscript: async (minTimestampMs: number) => {
 749→          const refreshed =
 750→            await this.refreshContextWindowUsageFromTranscript(minTimestampMs);
 751→          return refreshed ? this.contextWindowUsage : null;
 752→        },
 753→        queryStartedMs,
 754→        onQueryCompleted: () => {
 755→          queryCompleted = true;
 756→        },
 757→        providerExecution: this.providerOrchestrator
 758→          ? {
 759→              orchestrator: this.providerOrchestrator,
 760→              identity: this.resolveProviderIdentity(),
 761→              primaryProviderId: "anthropic",
 762→            }
 763→          : undefined,
 764→      });
 765→
 766→      if (runtimeResult.contextWindowUsage) {
 767→        this.contextWindowUsage = runtimeResult.contextWindowUsage;
 768→      }
 769→      if (
 770→        typeof runtimeResult.contextWindowSize === "number" &&
 771→        runtimeResult.contextWindowSize > 0
 772→      ) {
 773→        this.contextWindowSize = runtimeResult.contextWindowSize;
 774→      }
 775→      if (runtimeResult.lastUsage) {
 776→        this.lastUsage = runtimeResult.lastUsage;
 777→        this.accumulateUsage(this.lastUsage);
 778→      }
 779→
 780→      if (this.contextWindowUsage) {
 781→        const pct = (
 782→          (this.currentContextTokens / this.contextWindowSize) *
 783→          100
 784→        ).toFixed(1);
 785→        console.log(
 786→          `Context: ${this.currentContextTokens}/${this.contextWindowSize} (${pct}%)`
 787→        );
 788→      }
 789→    } catch (error) {
 790→      const isExpectedAbort =
 791→        isAbortError(error) && (queryCompleted || this.stopRequested);
 792→
 793→      if (isExpectedAbort) {
 794→        console.warn(`Suppressed expected abort (completed: ${queryCompleted})`);
 795→      } else {
 796→        console.error("Error in query:", error);
 797→        this.lastError = String(error).slice(0, 100);
 798→        this.lastErrorTime = new Date();
 799→        throw error;
 800→      }
 801→    } finally {
 802→      this.applyRuntimeState(finalizeQueryTransition(this.getRuntimeState()));
 803→      if (this._activityState !== "idle") {
 804→        this.setActivityState("idle");
 805→      }
 806→      this.abortController = null;
 807→      this.queryStarted = null;
 808→      this.currentTool = null;
 809→    }
 810→
 811→    const fullResponse = runtimeResult?.fullResponse || "No response from Claude.";
 812→
 813→    try {
 814→      this.lastActivity = new Date();
 815→      this.lastError = null;
 816→      this.lastErrorTime = null;
 817→
 818→      usageAfter = await captureUsageSnapshot();
 819→
 820→      const contextUsagePercent = this.contextWindowUsage
 821→        ? (this.currentContextTokens / this.contextWindowSize) * 100
 822→        : undefined;
 823→      const currentModelId = getModelForContext(modelContext);
 824→      const toolDurations = runtimeResult?.toolDurations ?? {};
 825→      const metadata = buildQueryRuntimeMetadata({
 826→        usageBefore,
 827→        usageAfter,
 828→        toolDurations,
 829→        queryStartedMs,
 830→        contextUsagePercent,
 831→        contextUsagePercentBefore,
 832→        modelDisplayName: MODEL_DISPLAY_NAMES[currentModelId] || currentModelId,
 833→        currentProvider: runtimeResult?.providerId,
 834→      });
 835→
 836→      for (const [toolName, stats] of Object.entries(toolDurations)) {
 837→        const existing = this.cumulativeToolDurations[toolName] || {
 838→          count: 0,
 839→          totalMs: 0,
 840→        };
 841→        this.cumulativeToolDurations[toolName] = {
 842→          count: existing.count + stats.count,
 843→          totalMs: existing.totalMs + stats.totalMs,
 844→        };
 845→      }
 846→
 847→      if (runtimeResult?.trailingSegmentText) {
 848→        await statusCallback(
 849→          "segment_end",
 850→          runtimeResult.trailingSegmentText,
 851→          runtimeResult.trailingSegmentId
 852→        );
 853→      }
 854→
 855→      await statusCallback("done", "", undefined, metadata);
 856→
 857→      const hasSteeringAtEnd = this.hasSteeringMessages();
 858→      const injectedCount = this.steering.getInjectedCount();
 859→      console.log(
 860→        `[STEERING DEBUG] End of query - buffer: ${this.steering.getSteeringCount()}, injected tracking: ${injectedCount}`
 861→      );
 862→
 863→      if (hasSteeringAtEnd) {
 864→        const steeringCount = this.getSteeringCount();
 865→        const steeringContent = this.peekSteering();
 866→        console.log(
 867→          `[STEERING] ${steeringCount} message(s) not delivered (text-only response)`
 868→        );
 869→        await statusCallback("steering_pending", steeringContent || "", undefined, {
 870→          ...metadata,
 871→          steeringCount,
 872→        } as QueryMetadata & { steeringCount: number });
 873→      }
 874→
 875→      if (this.chatCaptureService && this.sessionId) {
 876→        this.chatCaptureService
 877→          .captureAssistantMessage(
 878→            this.sessionKey,
 879→            this.sessionId,
 880→            getModelForContext(modelContext),
 881→            fullResponse,
 882→            {
 883→              tokenUsage: this.lastUsage
 884→                ? {
 885→                    input: this.lastUsage.input_tokens,
 886→                    output: this.lastUsage.output_tokens,
 887→                  }
 888→                : undefined,
 889→            }
 890→          )
 891→          .catch((err) =>
 892→            console.error("[ChatCapture] Failed to capture assistant message:", err)
 893→          );
 894→      }
 895→    } catch (postQueryError) {
 896→      console.error("[POST-QUERY] Error in post-query processing:", postQueryError);
 897→    }
 898→
 899→    return fullResponse;
 900→  }
