 902→  async kill(): Promise<KillResult> {
 903→    // Increment generation to invalidate any in-flight queries
 904→    this.applyRuntimeState(incrementGenerationTransition(this.getRuntimeState()));
 905→    console.log(`[KILL] Generation incremented to ${this._generation}`);
 906→
 907→    // Block any pending tools via preToolUseHook
 908→    this.applyRuntimeState(
 909→      requestStopDuringPreparingTransition(this.getRuntimeState())
 910→    );
 911→
 912→    // Abort any in-flight query
 913→    if (this.abortController) {
 914→      this.abortController.abort();
 915→      console.log("[KILL] Aborted in-flight query");
 916→    }
 917→
 918→    // Extract lost steering messages for caller to offer recovery
 919→    const lostMessages = this.steering.extractSteeringMessages();
 920→    if (lostMessages.length > 0) {
 921→      console.warn(
 922→        `[STEERING] Extracted ${lostMessages.length} message(s) during session kill`
 923→      );
 924→    }
 925→
 926→    this.applyRuntimeState(finalizeQueryTransition(this.getRuntimeState()));
 927→    this.sessionId = null;
 928→    this.lastActivity = null;
 929→    this.sessionStartTime = null;
 930→    this.totalInputTokens = 0;
 931→    this.totalOutputTokens = 0;
 932→    this.totalCacheReadTokens = 0;
 933→    this.totalCacheCreateTokens = 0;
 934→    this.totalQueries = 0;
 935→    this.cumulativeToolDurations = {};
 936→    this.steering.reset();
 937→    this.resetWarningFlags();
 938→    console.log("Session cleared");
 939→    return { count: lostMessages.length, messages: lostMessages };
 940→  }
 941→
 942→  markRestored(): void {
 943→    this.recentlyRestored = true;
 944→    this.messagesSinceRestore = 0;
 945→    this.resetWarningFlags();
 946→    console.log("Context restored - cooldown activated (50 messages)");
 947→  }
 948→
 949→  private resetWarningFlags(): void {
 950→    this.contextLimitWarned = false;
 951→    this.warned70 = false;
 952→    this.warned85 = false;
 953→    this.warned95 = false;
 954→    this.recentlyRestored = false;
 955→    this.messagesSinceRestore = 0;
 956→  }
 957→
 958→  restoreFromData(data: SessionData): KillResult {
 959→    // Extract lost steering messages for caller to offer recovery
 960→    const lostMessages = this.steering.extractSteeringMessages();
 961→    if (lostMessages.length > 0) {
 962→      console.warn(
 963→        `[STEERING] Extracted ${lostMessages.length} message(s) during session restore`
 964→      );
 965→    }
 966→
 967→    this.sessionId = data.session_id;
 968→    this.lastActivity = new Date();
 969→    this.totalInputTokens = data.totalInputTokens || 0;
 970→    this.totalOutputTokens = data.totalOutputTokens || 0;
 971→    this.totalQueries = data.totalQueries || 0;
 972→    this.sessionStartTime = data.sessionStartTime
 973→      ? new Date(data.sessionStartTime)
 974→      : null;
 975→    if (data.contextWindowUsage !== undefined)
 976→      this.contextWindowUsage = data.contextWindowUsage || null;
 977→    if (typeof data.contextWindowSize === "number" && data.contextWindowSize > 0)
 978→      this.contextWindowSize = data.contextWindowSize;
 979→    return { count: lostMessages.length, messages: lostMessages };
 980→  }
 981→
 982→  private accumulateUsage(u: TokenUsage): void {
 983→    if (!this.sessionStartTime) this.sessionStartTime = new Date();
 984→
 985→    this.totalInputTokens += u.input_tokens || 0;
 986→    this.totalOutputTokens += u.output_tokens || 0;
 987→    this.totalCacheReadTokens += u.cache_read_input_tokens || 0;
 988→    this.totalCacheCreateTokens += u.cache_creation_input_tokens || 0;
 989→    this.totalQueries++;
 990→
 991→    console.log(
 992→      `Usage: in=${u.input_tokens} out=${u.output_tokens} cache_read=${u.cache_read_input_tokens || 0} cache_create=${u.cache_creation_input_tokens || 0} cumulative=${this.currentContextTokens}`
 993→    );
 994→
 995→    const CONTEXT_LIMIT = this.contextWindowSize || 200_000;
 996→    const COOLDOWN_MESSAGES = 50;
 997→    const currentContext = this.currentContextTokens;
 998→
 999→    if (this.recentlyRestored) {
1000→      this.messagesSinceRestore++;
1001→      if (this.messagesSinceRestore >= COOLDOWN_MESSAGES) {
1002→        console.log("Cooldown period complete, re-enabling context limit monitoring");
1003→        this.resetWarningFlags();
1004→      }
1005→    }
1006→
1007→    // Reset contextLimitWarned if context dropped significantly (compaction detected)
1008→    if (this.contextLimitWarned && currentContext < CONTEXT_LIMIT * 0.8) {
1009→      console.log(
1010→        `[CONTEXT] Compaction detected: ${currentContext}/${CONTEXT_LIMIT} (${((currentContext / CONTEXT_LIMIT) * 100).toFixed(1)}%). Resetting contextLimitWarned.`
1011→      );
1012→      this.contextLimitWarned = false;
1013→    }
1014→
1015→    this.checkThreshold(currentContext, CONTEXT_LIMIT, 0.7, "warned70", "70% reached");
1016→    this.checkThreshold(currentContext, CONTEXT_LIMIT, 0.85, "warned85", "85% reached");
1017→    this.checkThreshold(
1018→      currentContext,
1019→      CONTEXT_LIMIT,
1020→      0.95,
1021→      "warned95",
1022→      "95% CRITICAL"
1023→    );
1024→
1025→    if (
1026→      currentContext >= CONTEXT_LIMIT * 0.9 &&
1027→      !this.contextLimitWarned &&
1028→      !this.recentlyRestored
1029→    ) {
1030→      this.contextLimitWarned = true;
1031→      const pct = ((currentContext / CONTEXT_LIMIT) * 100).toFixed(1);
1032→      console.log("[TELEMETRY] context_limit_approaching", {
1033→        currentContext,
1034→        threshold: CONTEXT_LIMIT * 0.9,
1035→        percentage: pct,
1036→        timestamp: new Date().toISOString(),
1037→      });
1038→      console.warn(
1039→        `⚠️  CONTEXT LIMIT APPROACHING: ${currentContext}/${CONTEXT_LIMIT} tokens (${pct}%) - SAVE REQUIRED`
1040→      );
1041→    }
1042→
1043→    // DISABLED: auto-save on every accumulation
1044→    // this.saveSession();
1045→  }
1046→
1047→  private checkThreshold(
1048→    current: number,
1049→    limit: number,
1050→    pct: number,
1051→    flag: "warned70" | "warned85" | "warned95",
1052→    label: string
1053→  ): void {
1054→    const threshold = Math.floor(limit * pct);
1055→    if (current >= threshold && !this[flag] && !this.recentlyRestored) {
1056→      this[flag] = true;
1057→      const percentage = ((current / limit) * 100).toFixed(1);
1058→      console.log(`[TELEMETRY] context_threshold_${Math.floor(pct * 100)}`, {
1059→        sessionId: this.sessionId?.slice(0, 8),
1060→        currentContext: current,
1061→        threshold,
1062→        tokensRemaining: limit - current,
1063→        percentage,
1064→        timestamp: new Date().toISOString(),
1065→      });
1066→      console.warn(`⚠️  Context: ${current}/${limit} (${percentage}%) - ${label}`);
1067→    }
1068→  }
1069→
1070→  private saveSession(): void {
1071→    if (!this.sessionId) return;
1072→
1073→    try {
1074→      const data: SessionData = {
1075→        session_id: this.sessionId,
1076→        saved_at: new Date().toISOString(),
1077→        working_dir: this.workingDir,
1078→        contextWindowUsage: this.contextWindowUsage,
1079→        contextWindowSize: this.contextWindowSize,
1080→        totalInputTokens: this.totalInputTokens,
1081→        totalOutputTokens: this.totalOutputTokens,
1082→        totalQueries: this.totalQueries,
1083→        sessionStartTime: this.sessionStartTime?.toISOString(),
1084→      };
1085→
1086→      if (!existsSync(SESSIONS_DIR)) {
1087→        mkdirSync(SESSIONS_DIR, { recursive: true });
1088→      }
1089→      const savePath = this.getSessionFilePath();
1090→      Bun.write(savePath, JSON.stringify(data));
1091→      console.log(
1092→        `Session saved to ${savePath} (context: ${this.totalInputTokens + this.totalOutputTokens} tokens)`
1093→      );
1094→    } catch (error) {
1095→      console.warn(`Failed to save session: ${error}`);
1096→    }
1097→  }
1098→
1099→  resumeLast(): [success: boolean, message: string] {
1100→    try {
1101→      const savePath = this.getSessionFilePath();
1102→      const file = Bun.file(savePath);
1103→      if (!file.size) return [false, "No saved session found"];
1104→
1105→      const data: SessionData = JSON.parse(readFileSync(savePath, "utf-8"));
1106→      if (!data.session_id) return [false, "Saved session file is empty"];
1107→      if (data.working_dir && data.working_dir !== WORKING_DIR) {
1108→        return [false, `Session was for different directory: ${data.working_dir}`];
1109→      }
1110→
1111→      this.sessionId = data.session_id;
1112→      this.lastActivity = new Date();
1113→      this.totalInputTokens = data.totalInputTokens || 0;
1114→      this.totalOutputTokens = data.totalOutputTokens || 0;
1115→      this.totalQueries = data.totalQueries || 0;
1116→      this.sessionStartTime = data.sessionStartTime
1117→        ? new Date(data.sessionStartTime)
1118→        : null;
1119→      if (data.contextWindowUsage !== undefined)
1120→        this.contextWindowUsage = data.contextWindowUsage || null;
1121→      if (typeof data.contextWindowSize === "number" && data.contextWindowSize > 0)
1122→        this.contextWindowSize = data.contextWindowSize;
1123→
1124→      const contextTokens = this.totalInputTokens + this.totalOutputTokens;
1125→      console.log(
1126→        `Resumed session ${data.session_id.slice(0, 8)}... (saved at ${data.saved_at}, context: ${contextTokens} tokens)`
1127→      );
1128→      return [
1129→        true,
1130→        `Resumed session \`${data.session_id.slice(0, 8)}...\` (saved at ${data.saved_at})`,
1131→      ];
1132→    } catch (error) {
1133→      console.error(`Failed to resume session: ${error}`);
1134→      return [false, `Failed to load session: ${error}`];
1135→    }
1136→  }
1137→
1138→  private getSessionFilePath(): string {
1139→    const safeKey = this.sessionKey.replace(/[:/]/g, "_");
1140→    return `${SESSIONS_DIR}/${safeKey}.json`;
1141→  }
1142→}
