  1→/**
  2→ * Text message handler for Claude Telegram Bot.
  3→ */
  4→
  5→import type { Context } from "grammy";
  6→import { Reactions } from "../constants/reactions";
  7→import { type ChatType } from "../security";
  8→import { sessionManager } from "../core/session/session-manager";
  9→import {
 10→  handlePendingDirectInput,
 11→  handlePendingParseTextChoice,
 12→} from "./text/direct-input-flow";
 13→import { runInboundGuard } from "./text/inbound-guard";
 14→import {
 15→  handleSteeringGate,
 16→  resolvePendingRecoveryContext,
 17→  runInterruptRoute,
 18→} from "./text/interrupt-flow";
 19→import { runQueryFlow, type QueryFlowParams } from "./text/query-flow";
 20→import { MessageQueue } from "../message-queue";
 21→
 22→// Bot username (set by index.ts after bot info is fetched)
 23→export let botUsername = "";
 24→export function setBotUsername(username: string): void {
 25→  botUsername = username;
 26→}
 27→
 28→// ─── Pre-execution Message Batching ───────────────────────────────────
 29→// When session is idle, batch rapid-fire messages via MessageQueue
 30→// so they hit Claude as a single combined prompt instead of N separate calls.
 31→
 32→const DEBOUNCE_MS = 500;
 33→
 34→interface PendingBatch {
 35→  queue: MessageQueue;
 36→  /** Most recent params — used for ctx, session, chatId etc. on flush */
 37→  latestParams: QueryFlowParams;
 38→  /** All enqueued messages in order */
 39→  messages: string[];
 40→}
 41→
 42→const pendingBatches = new Map<string, PendingBatch>();
 43→
 44→function getSessionKey(chatId: number, threadId?: number): string {
 45→  return threadId ? `${chatId}:${threadId}` : String(chatId);
 46→}
 47→
 48→async function flushBatch(key: string): Promise<void> {
 49→  const batch = pendingBatches.get(key);
 50→  if (!batch) return;
 51→
 52→  // Grab and clear
 53→  const messages = [...batch.messages];
 54→  const params = batch.latestParams;
 55→  pendingBatches.delete(key);
 56→
 57→  if (messages.length === 0) return;
 58→
 59→  const combined: string = messages.length === 1
 60→    ? messages[0]!
 61→    : messages.map((m, i) => `[${i + 1}] ${m}`).join("\n");
 62→
 63→  console.log(
 64→    `[BATCH] Flushing ${messages.length} message(s) for ${key}: "${combined.slice(0, 100)}..."`
 65→  );
 66→
 67→  await resolvePendingRecoveryContext({
 68→    ctx: params.ctx,
 69→    session: params.session,
 70→    chatId: params.chatId,
 71→  });
 72→
 73→  await runQueryFlow({
 74→    ...params,
 75→    message: combined,
 76→  });
 77→}
 78→
 79→/**
 80→ * Handle incoming text messages.
 81→ */
 82→export async function handleText(ctx: Context): Promise<void> {
 83→  const userId = ctx.from?.id;
 84→  const username = ctx.from?.username || "unknown";
 85→  const chatId = ctx.chat?.id;
 86→  const chatType = ctx.chat?.type as ChatType | undefined;
 87→  const threadId = ctx.message?.message_thread_id;
 88→  let message = ctx.message?.text;
 89→
 90→  if (!userId || !message || !chatId) {
 91→    return;
 92→  }
 93→
 94→  const inbound = await runInboundGuard({
 95→    ctx,
 96→    message,
 97→    chatType,
 98→    userId,
 99→    username,
100→    botUsername,
101→  });
102→  if (!inbound) {
103→    return;
104→  }
105→
106→  message = inbound.normalizedMessage;
107→  const { deliverInboundReaction } = inbound;
108→
109→  try {
110→    await deliverInboundReaction(Reactions.READ);
111→  } catch (error) {
112→    console.debug("Failed to add reaction to user message via boundary:", error);
113→  }
114→
115→  const session = sessionManager.getSession(chatId, threadId);
116→
117→  const directInputHandled = await handlePendingDirectInput({
118→    ctx,
119→    session,
120→    chatId,
121→    message,
122→    username,
123→    userId,
124→  });
125→  if (directInputHandled) {
126→    return;
127→  }
128→
129→  const parseTextChoiceHandled = await handlePendingParseTextChoice({
130→    ctx,
131→    session,
132→    chatId,
133→    message,
134→    username,
135→    userId,
136→  });
137→  if (parseTextChoiceHandled) {
138→    return;
139→  }
140→
141→  const interruptResult = await runInterruptRoute({
142→    ctx,
143→    session,
144→    message,
145→    chatId,
146→    threadId,
147→    deliverInboundReaction,
148→  });
149→  if (interruptResult.handled) {
150→    return;
151→  }
152→
153→  message = interruptResult.message;
154→  const { wasInterrupt } = interruptResult;
155→
156→  // Strip @mention from message if present (cleaner input for Claude)
157→  if (botUsername && message.includes(`@${botUsername}`)) {
158→    message = message.replace(new RegExp(`@${botUsername}\\s*`, "g"), "").trim();
159→  }
160→
161→  const steeringHandled = await handleSteeringGate({
162→    ctx,
163→    session,
164→    message,
165→    wasInterrupt,
166→    chatId,
167→    userId,
168→    username,
169→    deliverInboundReaction,
170→  });
171→  if (steeringHandled) {
172→    return;
173→  }
174→
175→  // ─── Pre-execution batching ───────────────────────────────────────
176→  // If session is idle, batch rapid-fire messages via debounce window.
177→  // If session is processing, steering gate already handled it above.
178→
179→  const threadId2 = ctx.message?.message_thread_id;
180→  const batchKey = getSessionKey(chatId, threadId2);
181→
182→  const queryParams: QueryFlowParams = {
183→    ctx,
184→    session,
185→    message,
186→    chatId,
187→    userId,
188→    username,
189→    deliverInboundReaction,
190→  };
191→
192→  const existing = pendingBatches.get(batchKey);
193→  if (existing) {
194→    // Additional message within debounce window — append
195→    existing.messages.push(message);
196→    existing.latestParams = queryParams;
197→    // Re-enqueue resets the debounce timer inside MessageQueue
198→    existing.queue.enqueue(message);
199→    console.log(
200→      `[BATCH] Appended message #${existing.messages.length} for ${batchKey}: "${message.slice(0, 60)}"`
201→    );
202→    return;
203→  }
204→
205→  // First message — create batch with debounce
206→  const batchState: PendingBatch = {
207→    queue: new MessageQueue({
208→      debounceMs: DEBOUNCE_MS,
209→      onFlush: () => flushBatch(batchKey),
210→      onError: (err) => console.error(`[BATCH] Flush error for ${batchKey}:`, err),
211→    }),
212→    latestParams: queryParams,
213→    messages: [message],
214→  };
215→  pendingBatches.set(batchKey, batchState);
216→  batchState.queue.enqueue(message);
217→
218→  console.log(
219→    `[BATCH] Started batch for ${batchKey}, debounce=${DEBOUNCE_MS}ms: "${message.slice(0, 60)}"`
220→  );
221→}
