  1→import type { Context } from "grammy";
  2→import type { ClaudeSession } from "../../core/session/session";
  3→import { sessionManager } from "../../core/session/session-manager";
  4→import { TelegramChoiceBuilder } from "../../utils/telegram-choice-builder";
  5→import { sendSystemMessage } from "../../utils/system-message";
  6→import { checkInterrupt } from "../../utils/interrupt";
  7→import { Reactions } from "../../constants/reactions";
  8→
  9→export interface InterruptRouteParams {
 10→  ctx: Context;
 11→  session: ClaudeSession;
 12→  message: string;
 13→  chatId: number;
 14→  threadId?: number;
 15→  deliverInboundReaction: (reaction: string) => Promise<void>;
 16→}
 17→
 18→export interface InterruptRouteResult {
 19→  handled: boolean;
 20→  message: string;
 21→  wasInterrupt: boolean;
 22→}
 23→
 24→export async function runInterruptRoute(
 25→  params: InterruptRouteParams
 26→): Promise<InterruptRouteResult> {
 27→  const { ctx, session, message, chatId, threadId, deliverInboundReaction } = params;
 28→  const wasInterrupt = message.startsWith("!");
 29→  const nextMessage = await checkInterrupt(message, session);
 30→
 31→  if (nextMessage.trim()) {
 32→    return { handled: false, message: nextMessage, wasInterrupt };
 33→  }
 34→
 35→  if (!wasInterrupt) {
 36→    return { handled: true, message: nextMessage, wasInterrupt };
 37→  }
 38→
 39→  const lostMessages = session.extractSteeringMessages();
 40→  if (lostMessages.length > 0) {
 41→    const sessionKey = sessionManager.deriveKey(chatId, threadId);
 42→    session.setPendingRecovery(lostMessages, chatId);
 43→
 44→    const keyboard = TelegramChoiceBuilder.buildLostMessageKeyboard(sessionKey);
 45→    const messageText = TelegramChoiceBuilder.buildLostMessageText(lostMessages, true);
 46→
 47→    try {
 48→      const sentMsg = await ctx.reply(messageText, {
 49→        reply_markup: keyboard,
 50→        parse_mode: "Markdown",
 51→      });
 52→      session.setPendingRecovery(lostMessages, chatId, sentMsg.message_id);
 53→    } catch (replyError) {
 54→      console.error("[INTERRUPT] Failed to send lost message UI:", replyError);
 55→      try {
 56→        await sendSystemMessage(ctx, "🛑 Stopped (had undelivered messages)");
 57→      } catch {}
 58→    }
 59→    return { handled: true, message: nextMessage, wasInterrupt };
 60→  }
 61→
 62→  try {
 63→    await sendSystemMessage(ctx, "🛑 Stopped");
 64→  } catch {
 65→    try {
 66→      await deliverInboundReaction(Reactions.INTERRUPTED);
 67→    } catch {}
 68→  }
 69→  return { handled: true, message: nextMessage, wasInterrupt };
 70→}
 71→
 72→export interface SteeringGateParams {
 73→  ctx: Context;
 74→  session: ClaudeSession;
 75→  message: string;
 76→  wasInterrupt: boolean;
 77→  chatId: number;
 78→  userId: number;
 79→  username: string;
 80→  deliverInboundReaction: (reaction: string) => Promise<void>;
 81→}
 82→
 83→export async function handleSteeringGate(params: SteeringGateParams): Promise<boolean> {
 84→  const {
 85→    ctx,
 86→    session,
 87→    message,
 88→    wasInterrupt,
 89→    chatId,
 90→    userId,
 91→    username,
 92→    deliverInboundReaction,
 93→  } = params;
 94→  if (!session.isProcessing) {
 95→    return false;
 96→  }
 97→
 98→  console.log(
 99→    `[STEERING] Message gated by isProcessing=true, queryState=${session.queryState}, msg="${message.slice(0, 50)}"`
100→  );
101→
102→  if (wasInterrupt) {
103→    const start = Date.now();
104→    while (session.isProcessing && Date.now() - start < 2000) {
105→      await Bun.sleep(50);
106→    }
107→    return false;
108→  }
109→
110→  const messageId = ctx.message?.message_id;
111→  const steeringContext = {
112→    chatId,
113→    userId,
114→    username,
115→    messageId,
116→    currentTool: session.currentTool,
117→    hasSteeringMessages: session.hasSteeringMessages(),
118→    timestamp: new Date().toISOString(),
119→  };
120→
121→  if (messageId === undefined) {
122→    console.error("[STEERING] CRITICAL: Missing message_id, cannot buffer steering", {
123→      ...steeringContext,
124→      messagePreview: message.slice(0, 100),
125→    });
126→    try {
127→      await ctx.reply(
128→        "⚠️ Unable to queue message (technical issue: missing message ID). Please try sending again."
129→      );
130→    } catch (replyError) {
131→      console.error(
132→        "Failed to notify user of missing message_id:",
133→        replyError,
134→        steeringContext
135→      );
136→      try {
137→        await deliverInboundReaction(Reactions.ERROR_SOMA);
138→      } catch {}
139→    }
140→    return true;
141→  }
142→
143→  const evicted = session.addSteering(
144→    message,
145→    messageId,
146→    session.currentTool || undefined
147→  );
148→
149→  if (evicted) {
150→    console.warn("[STEERING] Buffer full, oldest message evicted", {
151→      ...steeringContext,
152→      bufferSize: session.getSteeringCount(),
153→    });
154→
155→    let notified = false;
156→    try {
157→      await ctx.reply(
158→        "⚠️ **Message Queue Full**\n\nYour oldest queued message was dropped because Claude is very busy. Please wait for current task to complete."
159→      );
160→      notified = true;
161→    } catch (replyError) {
162→      console.error("Failed to notify via reply:", replyError, steeringContext);
163→      try {
164→        await deliverInboundReaction(Reactions.CANCELLED);
165→        notified = true;
166→      } catch (reactError) {
167→        console.error("Failed to notify via reaction:", reactError, steeringContext);
168→      }
169→    }
170→
171→    if (!notified) {
172→      console.error("[STEERING] CRITICAL: Could not notify user of message eviction", {
173→        ...steeringContext,
174→      });
175→    }
176→  } else {
177→    console.log("[STEERING] Buffered user message during execution", steeringContext);
178→    try {
179→      await deliverInboundReaction(Reactions.STEERING_BUFFERED);
180→    } catch (error) {
181→      console.debug("Failed to add steering reaction:", error, steeringContext);
182→    }
183→  }
184→
185→  return true;
186→}
187→
188→export interface RecoveryParams {
189→  ctx: Context;
190→  session: ClaudeSession;
191→  chatId: number;
192→}
193→
194→export async function resolvePendingRecoveryContext(
195→  params: RecoveryParams
196→): Promise<void> {
197→  const { ctx, session, chatId } = params;
198→  if (!session.hasPendingRecovery()) {
199→    return;
200→  }
201→  const recovery = session.getPendingRecovery();
202→  if (!recovery) {
203→    return;
204→  }
205→
206→  console.log(
207→    `[RECOVERY] Auto-resolving pending recovery (${recovery.messages.length} messages) as context for new message`
208→  );
209→
210→  const resolved = session.resolvePendingRecovery();
211→  if (resolved && resolved.length > 0) {
212→    const formattedContext = resolved
213→      .map((message) => {
214→        const ts = new Date(message.timestamp).toLocaleTimeString("en-US", {
215→          hour12: false,
216→        });
217→        return `[${ts}] ${message.content}`;
