 36→export function createQueryRuntimeHooks(
 37→  deps: QueryRuntimeHookDependencies
 38→): QueryRuntimeHooks {
 39→  const preToolUseHook: QueryRuntimeToolHook = async (
 40→    input: unknown,
 41→    _toolUseId: unknown,
 42→    _context: unknown
 43→  ): Promise<Record<string, unknown>> => {
 44→    const toolName = (input as { tool_name?: string }).tool_name || "unknown";
 45→    console.log(`[HOOK] PreToolUse fired for: ${toolName}`);
 46→
 47→    if (deps.getStopRequested()) {
 48→      console.log(`[HOOK] Abort requested - blocking tool: ${toolName}`);
 49→      throw new Error("Abort requested by user");
 50→    }
 51→
 52→    return {};
 53→  };
 54→
 55→  const postToolUseHook: QueryRuntimeToolHook = async (
 56→    input: unknown,
 57→    _toolUseId: unknown,
 58→    _context: unknown
 59→  ): Promise<Record<string, unknown>> => {
 60→    const toolName = (input as { tool_name?: string }).tool_name || "unknown";
 61→    console.log(`[HOOK] PostToolUse fired for: ${toolName}`);
 62→
 63→    const bufferSize = deps.getSteeringCount();
 64→    console.log(`[HOOK DEBUG] Buffer size at hook: ${bufferSize}`);
 65→
 66→    if (!bufferSize) {
 67→      return {};
 68→    }
 69→
 70→    const injectedCount = deps.trackBufferedMessagesForInjection();
 71→    const steering = deps.consumeSteering();
 72→    if (!steering) {
 73→      return {};
 74→    }
 75→
 76→    console.log(
 77→      `[STEERING] Injecting ${injectedCount} message(s) after ${toolName} (tracked for fallback: ${deps.getInjectedCount()})`
 78→    );
 79→    return {
 80→      systemMessage: `[USER SENT MESSAGE DURING EXECUTION]\n${steering}\n[END USER MESSAGE]`,
 81→    };
 82→  };
 83→
 84→  return {
 85→    preToolUseHook,
 86→    postToolUseHook,
 87→  };
