 29→export function mergeLatestUsage(
 30→  prev: TokenUsage | null,
 31→  update: Partial<TokenUsage>
 32→): TokenUsage {
 33→  function pick(updateVal: number | undefined, prevVal: number): number {
 34→    return typeof updateVal === "number" && updateVal > 0 ? updateVal : prevVal;
 35→  }
 36→
 37→  const base = prev ?? {
 38→    input_tokens: 0,
 39→    output_tokens: 0,
 40→    cache_read_input_tokens: 0,
 41→    cache_creation_input_tokens: 0,
 42→  };
 43→
 44→  return {
 45→    input_tokens: pick(update.input_tokens, base.input_tokens),
 46→    output_tokens:
 47→      typeof update.output_tokens === "number"
 48→        ? update.output_tokens
 49→        : base.output_tokens,
 50→    cache_read_input_tokens: pick(
 51→      update.cache_read_input_tokens,
 52→      base.cache_read_input_tokens ?? 0
 53→    ),
 54→    cache_creation_input_tokens: pick(
 55→      update.cache_creation_input_tokens,
 56→      base.cache_creation_input_tokens ?? 0
 57→    ),
 58→  };
 59→}
