110→export function readFileTail(path: string, maxBytes: number): string | null {
111→  try {
112→    const stats = statSync(path);
113→    const size = stats.size;
114→    const start = Math.max(0, size - maxBytes);
115→    const length = size - start;
116→
117→    const fd = openSync(path, "r");
118→    try {
119→      const buffer = Buffer.alloc(length);
120→      const read = readSync(fd, buffer, 0, length, start);
121→      if (read <= 0) return null;
122→      return buffer.subarray(0, read).toString("utf8");
123→    } finally {
124→      closeSync(fd);
125→    }
126→  } catch {
127→    return null;
128→  }
129→}
