131→export function extractMainAssistantContextUsageFromTranscriptLine(
132→  line: string,
133→  sessionId: string,
134→  minTimestampMs: number
135→): ContextWindowUsage | null {
136→  try {
137→    const parsed: unknown = JSON.parse(line);
138→    if (!parsed || typeof parsed !== "object") return null;
139→    const record = parsed as Record<string, unknown>;
140→
141→    if (record.type !== "assistant") return null;
142→    if (record.sessionId !== sessionId) return null;
143→    if ("isSidechain" in record && record.isSidechain !== false) return null;
144→
145→    const timestampStr = typeof record.timestamp === "string" ? record.timestamp : null;
146→    if (timestampStr) {
147→      const ts = Date.parse(timestampStr);
148→      if (!Number.isNaN(ts) && ts < minTimestampMs) return null;
149→    }
