  1→/**
  2→ * MessageQueue - Batches messages with debounce for idle-time optimization.
  3→ *
  4→ * Buffers incoming messages and auto-flushes after a configurable debounce window.
  5→ * Manual flush is available for immediate batch retrieval.
  6→ */
  7→
  8→export type Message = string;
  9→export type BatchPayload = Message[];
 10→
 11→export interface MessageQueueOptions {
 12→  /** Debounce window in milliseconds (default: 300, must be non-negative) */
