 28→  ctx: Context;
 29→  session: ClaudeSession;
 30→  message: string;
 31→  chatId: number;
 32→  userId: number;
 33→  username: string;
 34→  deliverInboundReaction: (reaction: string) => Promise<void>;
 35→}
 36→
 37→export async function runQueryFlow(params: QueryFlowParams): Promise<void> {
 38→  const { ctx, session, message, chatId, userId, username, deliverInboundReaction } =
 39→    params;
 40→  session.lastMessage = message;
 41→  const messageWithTimestamp = addTimestamp(message);
 42→  const stopProcessing = session.startProcessing();
 43→
 44→  try {
 45→    await deliverInboundReaction(Reactions.PROCESSING);
 46→  } catch {}
 47→
 48→  const typing = startTypingIndicator(ctx);
 49→  let state = new StreamingState();
 50→  let statusCallback = await createStatusCallback(ctx, state, session);
 51→  const MAX_RETRIES = 1;
 52→
 53→  try {
 54→    for (let attempt = 0; attempt <= MAX_RETRIES; attempt++) {
 55→      try {
 56→        const response = await session.sendMessageStreaming(
 57→          messageWithTimestamp,
 58→          statusCallback,
 59→          chatId
 60→        );
 61→
 62→        await auditLog(userId, username, "TEXT", message, response);
 63→
 64→        try {
 65→          await deliverInboundReaction(Reactions.COMPLETE);
 66→        } catch {}
 67→
 68→        const MAX_AUTO_CONTINUE_ROUNDS = 5;
 69→        let autoContinueRound = 0;
 70→
 71→        // Fix soma-uqb9: For text-only responses, PostToolUse hook never fires,
 72→        // so messages remain in steeringBuffer (not tracked via injectedSteering).
 73→        // Previously we called trackBufferedMessagesForInjection() here, but that
 74→        // COPIES to injectedSteering without clearing the buffer. Then
 75→        // restoreInjectedSteering() merges injected BACK into the still-populated
 76→        // buffer, duplicating every message (3 messages → 6).
 77→        //
 78→        // Fix: Skip the track→restore round-trip entirely for text-only responses.
 79→        // The auto-continue loop below already consumes directly from the buffer.
 80→        // For tool-use responses, postToolUseHook handles track+consume correctly.
 81→
 82→        while (true) {
 83→          // Restore any injected messages from tool-use hooks back to buffer
 84→          // (only relevant when postToolUseHook ran during the query)
 85→          const bufferBeforeRestore = session.getSteeringCount();
 86→          const restoredCount = session.restoreInjectedSteering();
 87→          const bufferAfterRestore = session.getSteeringCount();
 88→          console.log(
 89→            `[STEERING DEBUG] Round ${autoContinueRound}: Before restore: ${bufferBeforeRestore}, Restored: ${restoredCount}, After: ${bufferAfterRestore}`
 90→          );
 91→
 92→          const hasSteering = session.hasSteeringMessages();
 93→          console.log(
 94→            `[AUTO-CONTINUE] Round ${autoContinueRound}: hasSteeringMessages() = ${hasSteering}, buffer count = ${session.getSteeringCount()}`
 95→          );
 96→
 97→          if (!hasSteering) {
 98→            if (autoContinueRound === 0) {
 99→              console.log("[AUTO-CONTINUE] No pending steering messages");
100→            } else {
101→              console.log(
102→                `[AUTO-CONTINUE] Drained all steering after ${autoContinueRound} round(s)`
103→              );
104→            }
105→            break;
106→          }
107→
108→          if (autoContinueRound >= MAX_AUTO_CONTINUE_ROUNDS) {
109→            console.warn(
110→              `[AUTO-CONTINUE] Hit max rounds (${MAX_AUTO_CONTINUE_ROUNDS}), stopping. Remaining buffer: ${session.getSteeringCount()}`
111→            );
112→            break;
113→          }
114→
115→          autoContinueRound++;
116→          const steeringCount = session.getSteeringCount();
117→          console.log(
118→            `[AUTO-CONTINUE] Round ${autoContinueRound}: Processing ${steeringCount} pending message(s)`
119→          );
120→
121→          const steeringContent = session.consumeSteering();
122→          console.log(
123→            `[AUTO-CONTINUE] Round ${autoContinueRound}: Consumed: "${steeringContent?.slice(0, 100)}..."`
124→          );
125→
126→          if (!steeringContent) {
127→            console.warn(
128→              "[AUTO-CONTINUE] consumeSteering returned null/empty despite hasSteering=true"
129→            );
130→            break;
131→          }
132→
133→          try {
134→            await sendSystemMessage(
135→              ctx,
136→              `💬 <i>대기 메시지 ${steeringCount}개 처리 중...</i>`,
137→              {
138→                parse_mode: "HTML",
139→              }
140→            );
141→          } catch {}
142→
143→          const followUpMessage = `[이전 응답 중 보낸 메시지 - 지금 처리합니다]\n${steeringContent}`;
144→
145→          const followUpState = new StreamingState();
146→          const followUpCallback = await createStatusCallback(
147→            ctx,
148→            followUpState,
149→            session
150→          );
151→
