157→              followUpMessage,
158→              followUpCallback,
159→              chatId
160→            );
161→            console.log(
162→              `[AUTO-CONTINUE] Round ${autoContinueRound}: Follow-up complete, response length: ${followUpResponse.length}`
163→            );
164→            await auditLog(
165→              userId,
