170→            );
171→            await Bun.sleep(500);
172→          } catch (followUpError) {
173→            console.error(
174→              `[AUTO-CONTINUE] Round ${autoContinueRound}: Follow-up FAILED:`,
175→              followUpError
176→            );
177→            await sendSystemMessage(
178→              ctx,
179→              "⚠️ 대기 중인 메시지 처리 실패. 다시 보내주세요."
180→            );
181→            break;
182→          }
183→        }
184→
185→        if (session.needsSave) {
186→          const currentTokens = session.currentContextTokens;
187→          const windowSize = session.contextWindowSize;
188→          const percentage = ((currentTokens / windowSize) * 100).toFixed(1);
189→          await sendSystemMessage(
