216→              }
217→
218→              const saveIdFile = `${WORKING_DIR}/.last-save-id`;
219→              writeFileSync(saveIdFile, saveId, "utf-8");
220→
221→              if (
222→                !existsSync(saveIdFile) ||
223→                readFileSync(saveIdFile, "utf-8").trim() !== saveId
224→              ) {
225→                const error = "Failed to persist save ID - file not written correctly";
226→                console.error(error);
227→                await ctx.reply(`❌ ${error}`);
228→                throw new Error(error);
229→              }
230→
231→              console.log(`✅ Save ID captured & verified: ${saveId} → ${saveIdFile}`);
232→              console.log("[TELEMETRY] auto_save_success", {
233→                saveId,
234→                contextTokens: currentTokens,
235→                timestamp: new Date().toISOString(),
236→              });
237→
238→              await sendSystemMessage(
239→                ctx,
240→                `✅ **Context Saved**\n\n` +
241→                  `Save ID: \`${saveId}\`\n\n` +
242→                  `Please run: \`make up\` to restart with restored context.`,
243→                { parse_mode: "Markdown" }
244→              );
245→            } else {
