200→      throw new Error(`Unsafe command blocked: ${reason}`);
201→    }
202→  }
203→
204→  if (["Read", "Write", "Edit"].includes(toolName)) {
205→    const filePath = String(toolInput.file_path || "");
206→    if (filePath) {
207→      const isTmpRead =
208→        toolName === "Read" &&
209→        (TEMP_PATHS.some((p) => filePath.startsWith(p)) ||
210→          filePath.includes("/.claude/"));
211→
212→      if (!isTmpRead && !isPathAllowed(filePath)) {
213→        console.warn(`BLOCKED: File access outside allowed paths: ${filePath}`);
214→        await statusCallback("tool", `Access denied: ${filePath}`);
215→        throw new Error(`File access blocked: ${filePath}`);
216→      }
217→    }
218→  }
219→}
220→
221→function toProviderPermissionMode(
222→  permissionMode: Options["permissionMode"]
223→): ProviderQueryInput["permissionMode"] {
224→  if (permissionMode === "bypassPermissions") {
225→    return "bypass";
226→  }
227→  return "default";
228→}
229→
230→function mapProviderId(providerId: string): Provider {
231→  if (providerId === "codex" || providerId === "gemini") {
232→    return providerId;
233→  }
234→  return "anthropic";
235→}
236→
237→async function executeProviderRuntime(
238→  input: QueryRuntimeExecutionInput & {
239→    providerExecution: QueryRuntimeProviderExecutionInput;
240→  }
241→): Promise<QueryRuntimeExecutionResult> {
242→  const responseParts: string[] = [];
243→  let currentSegmentId = 0;
244→  let currentSegmentText = "";
245→  let lastTextUpdate = 0;
246→  let queryCompleted = false;
247→  let lastUsage: TokenUsage | null = null;
248→  let contextWindowUsage: ContextWindowUsage | null = null;
249→  let contextWindowSize: number | null = null;
250→  let generationMismatch = false;
251→  let usedProviderId = input.providerExecution.primaryProviderId;
252→
253→  let currentToolStart: { name: string; startMs: number } | null = null;
254→  const toolDurations: Record<string, { count: number; totalMs: number }> = {};
255→  const closeCurrentTool = () => {
256→    if (!currentToolStart) {
257→      return;
258→    }
259→    const duration = Date.now() - currentToolStart.startMs;
260→    const existing = toolDurations[currentToolStart.name] || {
261→      count: 0,
262→      totalMs: 0,
263→    };
264→    toolDurations[currentToolStart.name] = {
265→      count: existing.count + 1,
266→      totalMs: existing.totalMs + duration,
267→    };
268→    currentToolStart = null;
269→  };
270→
271→  const queryId = `${input.providerExecution.identity.tenantId}-${Date.now()}-${Math.random()
272→    .toString(36)
273→    .slice(2, 10)}`;
274→
275→  const providerInput: ProviderQueryInput = {
276→    queryId,
277→    identity: input.providerExecution.identity,
278→    prompt: input.prompt,
279→    modelId: input.options.model,
280→    workingDirectory: input.options.cwd,
281→    resumeSessionId: input.options.resume,
282→    maxThinkingTokens: input.options.maxThinkingTokens,
283→    mcpServers:
284→      (input.options.mcpServers as Readonly<Record<string, unknown>>) ?? undefined,
285→    additionalDirectories: input.options.additionalDirectories,
286→    systemPrompt:
287→      typeof input.options.systemPrompt === "string"
288→        ? input.options.systemPrompt
289→        : undefined,
290→    permissionMode: toProviderPermissionMode(input.options.permissionMode),
291→    hooks: input.options.hooks,
292→    pathToClaudeCodeExecutable: input.options.pathToClaudeCodeExecutable,
293→    allowDangerouslySkipPermissions: input.options.allowDangerouslySkipPermissions,
294→    abortController: input.options.abortController,
295→  };
296→
297→  const onProviderEvent = async (event: ProviderEvent): Promise<void> => {
298→    if (input.shouldStop()) {
299→      input.options.abortController.abort();
300→      return;
301→    }
302→
303→    if (input.queryGeneration !== input.getCurrentGeneration()) {
304→      generationMismatch = true;
305→      input.options.abortController.abort();
306→      return;
307→    }
308→
309→    if (event.type === "session") {
310→      input.onSessionId(event.providerSessionId);
311→      return;
312→    }
313→
314→    if (event.type === "tool") {
315→      if (event.phase === "start") {
316→        const toolInput =
317→          event.payload && typeof event.payload === "object"
318→            ? (event.payload as Record<string, unknown>)
319→            : {};
320→        await validateToolInput(event.toolName, toolInput, input.statusCallback);
321→
322→        if (currentSegmentText) {
323→          await input.statusCallback(
324→            "segment_end",
325→            currentSegmentText,
326→            currentSegmentId
327→          );
328→          currentSegmentId++;
329→          currentSegmentText = "";
330→        }
331→
332→        closeCurrentTool();
333→        currentToolStart = { name: event.toolName, startMs: Date.now() };
334→
335→        const toolDisplay = formatToolStatus(event.toolName, toolInput);
336→        input.onToolDisplay(toolDisplay);
337→        console.log(`Tool: ${toolDisplay}`);
338→        await input.statusCallback("tool", toolDisplay);
339→      } else {
340→        closeCurrentTool();
341→      }
342→      return;
343→    }
344→
345→    if (event.type === "text") {
346→      closeCurrentTool();
347→      responseParts.push(event.delta);
348→      currentSegmentText += event.delta;
349→
350→      const now = Date.now();
351→      if (
352→        now - lastTextUpdate > STREAMING_THROTTLE_MS &&
353→        currentSegmentText.length > 20
354→      ) {
355→        await input.statusCallback("text", currentSegmentText, currentSegmentId);
356→        lastTextUpdate = now;
357→      }
358→      return;
359→    }
360→
361→    if (event.type === "usage") {
362→      lastUsage = {
363→        input_tokens: event.usage.inputTokens,
364→        output_tokens: event.usage.outputTokens,
365→        cache_read_input_tokens: event.usage.cacheReadInputTokens || 0,
366→        cache_creation_input_tokens: event.usage.cacheCreationInputTokens || 0,
367→      };
368→      if (
369→        !contextWindowUsage &&
370→        lastUsage.input_tokens +
371→          (lastUsage.cache_read_input_tokens || 0) +
372→          (lastUsage.cache_creation_input_tokens || 0) >
373→          0
374→      ) {
375→        contextWindowUsage = {
376→          input_tokens: lastUsage.input_tokens,
377→          cache_creation_input_tokens: lastUsage.cache_creation_input_tokens || 0,
378→          cache_read_input_tokens: lastUsage.cache_read_input_tokens || 0,
379→        };
380→      }
381→      return;
382→    }
383→
384→    if (event.type === "context") {
385→      contextWindowUsage = {
386→        input_tokens: event.usedTokens,
387→        cache_creation_input_tokens: 0,
388→        cache_read_input_tokens: 0,
389→      };
390→      contextWindowSize = event.maxTokens;
391→      return;
392→    }
393→
394→    if (event.type === "done") {
395→      console.log("Response complete");
396→      closeCurrentTool();
397→      if (event.reason === "completed") {
398→        queryCompleted = true;
399→        input.onQueryCompleted?.();
400→      }
401→    }
402→  };
403→
404→  try {
405→    const result = await input.providerExecution.orchestrator.executeProviderQuery({
406→      primaryProviderId: input.providerExecution.primaryProviderId,
407→      fallbackProviderId: input.providerExecution.fallbackProviderId,
408→      input: providerInput,
409→      onEvent: onProviderEvent,
410→    });
411→    usedProviderId = result.providerId;
412→  } catch (error) {
413→    if (!generationMismatch) {
414→      closeCurrentTool();
415→      throw error;
416→    }
417→  }
418→
419→  if (!contextWindowUsage && queryCompleted) {
420→    const refreshedUsage = await input.onRefreshContextWindowUsageFromTranscript(
421→      input.queryStartedMs
422→    );
423→    if (refreshedUsage) {
424→      contextWindowUsage = refreshedUsage;
425→    }
426→  }
427→
428→  closeCurrentTool();
429→
430→  return {
431→    providerId: mapProviderId(usedProviderId),
432→    fullResponse: responseParts.join("") || "No response from Claude.",
433→    trailingSegmentText: currentSegmentText,
434→    trailingSegmentId: currentSegmentId,
435→    toolDurations,
436→    contextWindowUsage,
437→    contextWindowSize,
438→    lastUsage,
439→    queryCompleted,
440→  };
441→}
442→
443→export async function executeQueryRuntime(
444→  input: QueryRuntimeExecutionInput
445→): Promise<QueryRuntimeExecutionResult> {
446→  if (input.providerExecution) {
447→    return executeProviderRuntime({
448→      ...input,
449→      providerExecution: input.providerExecution,
450→    });
451→  }
452→
453→  const queryFactory = input.queryFactory ?? query;
454→  const queryInstance = queryFactory({
455→    prompt: input.prompt,
456→    options: input.options,
457→  }) as AsyncGenerator<SDKMessage>;
458→
459→  const responseParts: string[] = [];
460→  let currentSegmentId = 0;
461→  let currentSegmentText = "";
462→  let lastTextUpdate = 0;
463→  let queryCompleted = false;
464→  let lastCallUsage: TokenUsage | null = null;
465→  let lastUsage: TokenUsage | null = null;
466→  let contextWindowUsage: ContextWindowUsage | null = null;
467→  let contextWindowSize: number | null = null;
468→
469→  let currentToolStart: { name: string; startMs: number } | null = null;
470→  const toolDurations: Record<string, { count: number; totalMs: number }> = {};
471→  const closeCurrentTool = () => {
472→    if (!currentToolStart) {
473→      return;
474→    }
475→    const duration = Date.now() - currentToolStart.startMs;
476→    const existing = toolDurations[currentToolStart.name] || {
477→      count: 0,
478→      totalMs: 0,
479→    };
480→    toolDurations[currentToolStart.name] = {
481→      count: existing.count + 1,
482→      totalMs: existing.totalMs + duration,
483→    };
484→    currentToolStart = null;
485→  };
486→
487→  for await (const event of queryInstance) {
488→    if (input.shouldStop()) {
489→      console.log("Query aborted by user");
490→      break;
491→    }
492→
493→    if (event.type === "stream_event") {
494→      const raw = event.event;
495→      const usage: unknown =
496→        raw.type === "message_start"
497→          ? raw.message.usage
498→          : raw.type === "message_delta"
499→            ? raw.usage
500→            : null;
501→
502→      if (usage && typeof usage === "object") {
503→        lastCallUsage = mergeLatestUsage(lastCallUsage, usage as Partial<TokenUsage>);
504→      }
505→    }
506→
507→    if (event.type === "system") {
508→      const sysEvent = event as {
509→        subtype?: string;
510→        compact_metadata?: { trigger: string; pre_tokens: number };
511→        status?: string | null;
512→      };
513→      if (sysEvent.subtype === "compact_boundary") {
514→        const trigger = sysEvent.compact_metadata?.trigger ?? "unknown";
515→        const preTokens = sysEvent.compact_metadata?.pre_tokens ?? 0;
516→        console.log(
517→          `[COMPACT] ${trigger} compact triggered (pre_tokens: ${preTokens})`
518→        );
519→        await input.statusCallback(
520→          "system",
521→          `🔄 Context compacting (${trigger}, ${preTokens} tokens)...`
522→        );
523→      }
524→      if (sysEvent.subtype === "status" && sysEvent.status === "compacting") {
525→        console.log("[COMPACT] Compaction in progress...");
526→      }
527→    }
528→
529→    if (event.session_id) {
530→      if (input.queryGeneration !== input.getCurrentGeneration()) {
531→        console.log(
532→          `[GENERATION] Session killed mid-query (gen ${input.queryGeneration} vs ${input.getCurrentGeneration()}), ignoring session_id`
533→        );
534→        break;
535→      }
536→      input.onSessionId(event.session_id);
537→    }
538→
539→    if (event.type === "assistant") {
540→      for (const block of event.message.content) {
541→        if (block.type === "thinking" && block.thinking) {
542→          console.log(`THINKING BLOCK: ${block.thinking.slice(0, 100)}...`);
543→          await input.statusCallback("thinking", block.thinking);
544→        }
545→
546→        if (block.type === "tool_use") {
547→          const toolName = block.name;
548→          const toolInput = block.input as Record<string, unknown>;
549→          await validateToolInput(toolName, toolInput, input.statusCallback);
550→
551→          if (currentSegmentText) {
552→            await input.statusCallback(
553→              "segment_end",
554→              currentSegmentText,
555→              currentSegmentId
556→            );
557→            currentSegmentId++;
558→            currentSegmentText = "";
559→          }
560→
561→          closeCurrentTool();
562→          currentToolStart = { name: toolName, startMs: Date.now() };
563→
564→          const toolDisplay = formatToolStatus(toolName, toolInput);
565→          input.onToolDisplay(toolDisplay);
566→          console.log(`Tool: ${toolDisplay}`);
567→          await input.statusCallback("tool", toolDisplay);
568→        }
569→
570→        if (block.type === "text") {
571→          closeCurrentTool();
572→          responseParts.push(block.text);
573→          currentSegmentText += block.text;
574→
575→          const now = Date.now();
576→          if (
577→            now - lastTextUpdate > STREAMING_THROTTLE_MS &&
578→            currentSegmentText.length > 20
579→          ) {
580→            await input.statusCallback("text", currentSegmentText, currentSegmentId);
581→            lastTextUpdate = now;
582→          }
583→        }
584→      }
585→    }
586→
587→    if (event.type === "result") {
588→      console.log("Response complete");
589→      closeCurrentTool();
590→      queryCompleted = true;
591→      input.onQueryCompleted?.();
592→
593→      const contextWindowFromClaudeCode = (() => {
594→        const cw = (event as unknown as { context_window?: unknown }).context_window;
595→        if (!isClaudeCodeContextWindow(cw) || !cw.current_usage) return null;
596→
597→        const cu = cw.current_usage;
598→        const usage = {
599→          input_tokens: typeof cu.input_tokens === "number" ? cu.input_tokens : 0,
600→          cache_creation_input_tokens:
601→            typeof cu.cache_creation_input_tokens === "number"
602→              ? cu.cache_creation_input_tokens
603→              : 0,
604→          cache_read_input_tokens:
605→            typeof cu.cache_read_input_tokens === "number"
606→              ? cu.cache_read_input_tokens
607→              : 0,
608→        };
609→
610→        return hasContextWindowUsage(usage)
611→          ? { usage, size: cw.context_window_size || null }
612→          : null;
613→      })();
614→
615→      if (contextWindowFromClaudeCode) {
616→        contextWindowUsage = contextWindowFromClaudeCode.usage;
617→        if (
618→          typeof contextWindowFromClaudeCode.size === "number" &&
619→          contextWindowFromClaudeCode.size > 0
620→        ) {
621→          contextWindowSize = contextWindowFromClaudeCode.size;
622→        }
623→      } else if (lastCallUsage) {
624→        const usage = {
625→          input_tokens: lastCallUsage.input_tokens || 0,
626→          cache_creation_input_tokens: lastCallUsage.cache_creation_input_tokens || 0,
627→          cache_read_input_tokens: lastCallUsage.cache_read_input_tokens || 0,
628→        };
629→        if (hasContextWindowUsage(usage)) {
630→          contextWindowUsage = usage;
631→        }
632→      } else if ("usage" in event && event.usage) {
633→        const u = event.usage as unknown as TokenUsage;
634→        const usage = {
635→          input_tokens: u.input_tokens || 0,
636→          cache_creation_input_tokens: u.cache_creation_input_tokens || 0,
637→          cache_read_input_tokens: u.cache_read_input_tokens || 0,
638→        };
639→        if (hasContextWindowUsage(usage)) {
640→          contextWindowUsage = usage;
641→        }
642→      }
643→
644→      const refreshedUsage = await input.onRefreshContextWindowUsageFromTranscript(
645→        input.queryStartedMs
646→      );
647→      if (refreshedUsage) {
648→        contextWindowUsage = refreshedUsage;
649→      }
650→
651→      if ("modelUsage" in event && event.modelUsage) {
652→        type ModelUsageEntry = {
653→          inputTokens: number;
654→          outputTokens: number;
655→          cacheReadInputTokens: number;
656→          cacheCreationInputTokens: number;
657→          contextWindow: number;
658→        };
659→        const modelUsage = event.modelUsage as Record<string, ModelUsageEntry>;
660→        let detectedContextWindow = 0;
661→        let totalIn = 0;
662→        let totalOut = 0;
663→        let totalCacheRead = 0;
664→        let totalCacheCreate = 0;
665→
666→        for (const mu of Object.values(modelUsage)) {
667→          if (!mu) continue;
668→          if (
669→            typeof mu.contextWindow === "number" &&
670→            mu.contextWindow > detectedContextWindow
671→          ) {
672→            detectedContextWindow = mu.contextWindow;
673→          }
674→          totalIn += mu.inputTokens || 0;
675→          totalOut += mu.outputTokens || 0;
676→          totalCacheRead += mu.cacheReadInputTokens || 0;
677→          totalCacheCreate += mu.cacheCreationInputTokens || 0;
678→        }
679→
680→        if (detectedContextWindow > 0) {
681→          contextWindowSize = detectedContextWindow;
682→        }
683→
684→        lastUsage = {
685→          input_tokens: totalIn,
686→          output_tokens: totalOut,
687→          cache_read_input_tokens: totalCacheRead,
688→          cache_creation_input_tokens: totalCacheCreate,
689→        };
690→
691→        if (!contextWindowUsage && totalIn + totalCacheRead + totalCacheCreate > 0) {
692→          contextWindowUsage = {
693→            input_tokens: totalIn,
694→            cache_creation_input_tokens: totalCacheCreate,
695→            cache_read_input_tokens: totalCacheRead,
696→          };
697→        }
698→      } else if ("usage" in event && event.usage) {
699→        lastUsage = event.usage as TokenUsage;
700→      }
701→    }
702→  }
703→
704→  closeCurrentTool();
705→
706→  return {
707→    providerId: "anthropic",
708→    fullResponse: responseParts.join("") || "No response from Claude.",
709→    trailingSegmentText: currentSegmentText,
710→    trailingSegmentId: currentSegmentId,
711→    toolDurations,
712→    contextWindowUsage,
713→    contextWindowSize,
714→    lastUsage,
715→    queryCompleted,
716→  };
717→}
718→
719→export interface BuildQueryRuntimeMetadataInput {
720→  usageBefore: UsageSnapshot | null;
721→  usageAfter: UsageSnapshot | null;
722→  toolDurations: Record<string, { count: number; totalMs: number }>;
723→  queryStartedMs: number;
724→  queryEndedMs?: number;
725→  contextUsagePercent?: number;
726→  contextUsagePercentBefore?: number;
727→  modelDisplayName?: string;
728→  currentProvider?: Provider;
729→}
730→
731→export function buildQueryRuntimeMetadata(
732→  input: BuildQueryRuntimeMetadataInput
733→): QueryMetadata {
734→  return {
735→    usageBefore: input.usageBefore,
736→    usageAfter: input.usageAfter,
737→    toolDurations: input.toolDurations,
738→    queryDurationMs: (input.queryEndedMs ?? Date.now()) - input.queryStartedMs,
739→    contextUsagePercent: input.contextUsagePercent,
740→    contextUsagePercentBefore: input.contextUsagePercentBefore,
741→    currentProvider: input.currentProvider ?? "anthropic",
742→    modelDisplayName: input.modelDisplayName,
743→  };
744→}
